<?php

declare(strict_types=1);

namespace Kocluk\Api\Support;

/**
 * Random identifiers and token helpers.
 *
 * Row ids are generated by the client; the server only mints UUIDs for users
 * and tokens for sessions, password resets and e-mail verification.
 */
final class Uuid
{
    public static function v4(): string
    {
        $bytes = random_bytes(16);

        // RFC 4122: version 4 and the IETF variant bits.
        $bytes[6] = chr((ord($bytes[6]) & 0x0f) | 0x40);
        $bytes[8] = chr((ord($bytes[8]) & 0x3f) | 0x80);

        $hex = bin2hex($bytes);

        return substr($hex, 0, 8)
            . '-' . substr($hex, 8, 4)
            . '-' . substr($hex, 12, 4)
            . '-' . substr($hex, 16, 4)
            . '-' . substr($hex, 20, 12);
    }

    /**
     * URL-safe random token without base64 padding; 32 bytes by default.
     */
    public static function token(int $bytes = 32): string
    {
        return rtrim(strtr(base64_encode(random_bytes($bytes)), '+/', '-_'), '=');
    }

    /**
     * Stored form of a session/reset token; the raw token never hits the DB.
     */
    public static function hashToken(string $token): string
    {
        return hash('sha256', $token);
    }
}
